export function Vidrio({ s, size = 24 }: { s: Sec; size?: number }): JSX.Element {
  const id = useId().replace(/:/g, "");
  const p = PARTS[s];
  // Capas: vd-bk (sólido) y vd-gl (vidrio + detalle) se separan al pasar (parallax); vd-gx lleva el gesto propio del ícono.
  // ponytail: la forma de atrás se pinta dos veces (nítida y desenfocada) en vez de <use>, para que el CSS de hover la alcance.
  return <><style href="concorde-vidrio" precedence="default">{VIDRIO_CSS}</style><svg className={`vd vd--${s}`} viewBox="0 0 48 48" width={size} height={size} aria-hidden>
    <defs>
      <clipPath id={`${id}c`}>{p.front}</clipPath>
      <filter id={`${id}f`} x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="3.2" /></filter>
    </defs>
    <g className="vd-bk">{p.back}</g>
    <g className="vd-gl"><g className="vd-gx">
      <g clipPath={`url(#${id}c)`}>
        <g className="vd-bl" filter={`url(#${id}f)`}>{p.back}</g>
        <g className="vd-glass">{p.front}</g>
        <g className="vd-edge">{p.front}</g>
      </g>
      {p.detail}
    </g></g>
  </svg></>;
}

/* Marco de las landings (el del Index, HomeIndexRebase): lienzo de 1024 centrado sobre el morado del header.
   Abierto 226 + 798 · cerrado 76 + 948. --sb lo fija el estado del sidebar. */
.root { min-height: 100vh; background: #2E0F70; }
.root, .root * { box-sizing: border-box; }
.desktopShell { --sb: 226px; display: grid; grid-template-columns: var(--sb) minmax(0, 1fr);
  grid-template-rows: 64px minmax(0, 1fr); width: min(100%, 1024px); min-width: 0; margin: 0 auto;
  transition: grid-template-columns 0.28s cubic-bezier(0.4, 0, 0.2, 1); }
.desktopShell[data-collapsed] { --sb: 76px; }
.desktopShell > header { position: sticky; top: 0; z-index: 4; grid-column: 2; grid-row: 1; }
/* La cabecera del Sidebar (logo + hamburguesa) mide 226 aunque el sidebar se cierre a 76 y va sobre el header. */
.sidebarRail { position: sticky; top: 0; z-index: 5; grid-column: 1; grid-row: 1 / -1; align-self: start; height: 100dvh; overflow: visible; }
.mainColumn { min-width: 0; grid-column: 2; grid-row: 2; background: #ffffff; }
.mobileShell { display: none; min-width: 0; overflow-x: clip; background: #fff; }
.brandLogo { display: block; width: 119px; height: 45px; object-fit: contain; }
.mobileBrand { display: inline-flex; align-items: center; gap: 10px; }
.mobileLogo { display: block; width: 96px; height: 30px; object-fit: contain; }

@media (max-width: 1023px) {
  .desktopShell { display: none; }
  .mobileShell { display: block; }
  .mobileShell, .mobileShell :global(.sbm-root), .mobileShell :global([data-block="header"]) {
    width: 100% !important; max-width: 100% !important; }
  .mobileShell > header { position: sticky; top: 0; z-index: 8; }
}

"use client";

/**
 * LandingShell — marco de las landings de VMC (Valoriza, Vendo Mis Cosas): el mismo del Index.
 * Escritorio: lienzo de 1024 con Sidebar (abierto 226, cerrado 76) y Header; el sidebar empuja al contenido.
 * Bajo 1024 px: Header con hamburguesa y el Sidebar como drawer (SidebarMobile).
 * El contenido se monta dos veces (escritorio y celular) y el CSS muestra uno; `body(id)` recibe "d" o "m"
 * para que los ids del contenido no se repitan.
 */
import { useEffect, useState } from "react";
import type { JSX, ReactNode } from "react";
import Header from "@/concorde/bloques/header/desktop/Header";
import Sidebar from "@/concorde/bloques/sidebar/desktop/Sidebar";
import SidebarMobile, { SidebarMenuButton } from "@/concorde/bloques/sidebar/mobile/SidebarMobile";
import shell from "./LandingShell.module.css";

export type LandingShellProps = {
  /** Contenido de la columna principal. */
  body: (id: "d" | "m") => ReactNode;
  /** Logo de la marca (por defecto, el de VMC del Index). */
  logoSrc?: string;
};

function BrandLogo({ className, src }: { className: string; src: string }): JSX.Element {
  return <img className={className} src={src} alt="VMC Subastas" />;
}

export default function LandingShell({ body, logoSrc = "/index/brand/logo-voyager.svg" }: LandingShellProps): JSX.Element {
  const [sidebarHeight, setSidebarHeight] = useState(900);
  const [collapsed, setCollapsed] = useState(true);
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => {
    const resize = () => setSidebarHeight(Math.max(720, window.innerHeight));
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  return (
    <div className={shell.root}>
      <div className={shell.desktopShell} data-collapsed={collapsed || undefined}>
        <Header width="100%" />
        <aside className={shell.sidebarRail} aria-label="Navegación de VMC">
          <Sidebar height={sidebarHeight} contentHeight={sidebarHeight} headerHeight={64} logo={<BrandLogo className={shell.brandLogo} src={logoSrc} />}
            collapsed={collapsed} onCollapsedChange={setCollapsed} />
        </aside>
        <main className={shell.mainColumn}>{body("d")}</main>
      </div>
      <div className={shell.mobileShell}>
        <SidebarMobile open={menuOpen} onOpenChange={setMenuOpen}>
          <Header width="100%" logo={
            <div className={shell.mobileBrand}>
              <SidebarMenuButton onClick={() => setMenuOpen(true)} expanded={menuOpen} />
              <BrandLogo className={shell.mobileLogo} src={logoSrc} />
            </div>
          } />
          {body("m")}
        </SidebarMobile>
      </div>
    </div>
  );
}

