 */

import { useId } from "react";
import type { JSX, ReactNode } from "react";

const STYLE_ID = "concorde-sbheader-styles";
const STYLES = `
.psb-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: none;
